Change to:
```typescript
const MAX_SLUG_LENGTH = 50;

// Parse --title argument
const titleArg = process.argv.find(arg => arg.startsWith('--title='));
if (!titleArg) {
  console.log(JSON.stringify({ error: true, message: 'Usage: next-id.cjs --title="Task title"' }));
  process.exit(1);
}
const title = titleArg.slice('--title='.length);

// Find highest ID (folder names can be "001" or "001-slug-here")
let highest = 0;
for (const folderName of folders) {
  const match = folderName.match(/^(\d+)/);
  if (match) {
    const id = parseInt(match[1], 10);
    if (!isNaN(id) && id > highest) {
      highest = id;
    }
  }
}

// Generate slug
const slug = slugify(title, { lower: true, strict: true }).slice(0, MAX_SLUG_LENGTH);
const paddedNumber = (highest + 1).toString().padStart(padding, '0');
const nextId = `${paddedNumber}-${slug}`;
```

- Modify findTaskFile to scan task folders and match by numeric prefix
- Use /^(\d+)/ regex to extract numeric portion from input ID
- Find folder that starts with the same numeric prefix
- This handles both "021" input finding "021-slug/" and "021-slug" input finding "021-slug/"

Current code (lines 13-18):
```typescript
function findTaskFile(id: string): string | null {
  const taskPath = path.join(TASKS_DIR, id, 'task.xml');
  if (fs.existsSync(taskPath)) {
    return taskPath.replace(/\\/g, '/');
  }
  return null;
}
```

Change to:
```typescript
function findTaskFile(id: string): string | null {
  // Extract numeric prefix from input (handles both "021" and "021-slug")
  const numericMatch = id.match(/^(\d+)/);
  if (!numericMatch) {
    return null;
  }
  const numericPrefix = numericMatch[1];

  // First try exact match (for legacy numeric folders)
  const exactPath = path.join(TASKS_DIR, id, 'task.xml');
  if (fs.existsSync(exactPath)) {
    return exactPath.replace(/\\/g, '/');
  }

  // Scan for folder starting with numeric prefix
  if (!fs.existsSync(TASKS_DIR)) {
    return null;
  }
  const folders = fs.readdirSync(TASKS_DIR, { withFileTypes: true })
    .filter(f => f.isDirectory())
    .map(f => f.name);

  for (const folder of folders) {
    const folderMatch = folder.match(/^(\d+)/);
    if (folderMatch && folderMatch[1] === numericPrefix) {
      const taskPath = path.join(TASKS_DIR, folder, 'task.xml');
      if (fs.existsSync(taskPath)) {
        return taskPath.replace(/\\/g, '/');
      }
    }
  }

  return null;
}
```

